@if($isAdmin)<script>(()=>{const modal=document.getElementById('review-modal'),form=document.getElementById('review-form'),money=v=>`RM ${Number(v).toLocaleString('ms-MY',{minimumFractionDigits:2,maximumFractionDigits:2})}`;document.querySelectorAll('[data-review]').forEach(button=>button.addEventListener('click',()=>{const report=JSON.parse(button.dataset.review);document.getElementById('review-name').textContent=report.staff_name;document.getElementById('review-date').textContent=`${report.sales_date} · ${report.shift}`;document.getElementById('review-cash').textContent=money(report.cash_sales);document.getElementById('review-online').textContent=money(report.online_sales);document.getElementById('review-total').textContent=money(Number(report.cash_sales)+Number(report.online_sales));document.getElementById('review-staff-note').textContent=report.staff_notes||'— Tiada catatan —';form.action=`{{ url('/laporan') }}/${report.id}/semak`;form.querySelector('textarea').value=report.admin_notes||'';modal.classList.remove('hidden')}));document.querySelectorAll('[data-close-modal]').forEach(button=>button.addEventListener('click',()=>modal.classList.add('hidden')));modal.addEventListener('click',event=>{if(event.target===modal)modal.classList.add('hidden')})})();</script>@endif
